/**
 * 返回首页：始终整页回到门户（禅道 5983 最终口径）。
 *
 * 门户地址读参数配置 sys.portal.index.url（指向门户对内首页 /#/index），
 * 落点由门户按自身登录态决定，管理端不猜登录态：
 *   · 门户有登录记录 → 门户路由放行 /index，落到「对内首页」；
 *   · 门户无登录记录 → 门户路由把 /index 导向「对外首页」/UnifiedLogin，
 *     且不带 redirect（见门户仓库 router/index.js 的 handleUnauthenticatedRoutes）。
 *
 * 6cc5eba2c 曾误改成站内回管理端首页（需求理解错误，已废弃）。
 * 配置缺失或请求失败时兜底回管理端落地页；重复导航要刷新给可见反馈：
 * 真实落地页是 /todo，不能只在 hash 含 /index 时才 reload。
 */
goHome() {
  this.$post('/system/config/getByKey', { configKey: PORTAL_INDEX_URL_KEY })
    .then((res) => {
      const url = typeof res?.data === 'string' ? res.data.trim() : ''
      if (isHttpUrl(url)) {
        this.redirectToPortal(url)
        return
      }
      this.pushDefaultIndex()
    })
    .catch(() => this.pushDefaultIndex())
},
/** 整页跳到门户；已是同一地址时强制刷新，避免 replace 到同址无反应 */
redirectToPortal(url) {
  const current = window.location.href
  const samePage = url.replace(/#.*$/, '') === current.replace(/#.*$/, '')
  if (samePage) {
    window.location.reload()
  } else {
    window.location.replace(url)
  }
},
/** 兜底：回管理端落地页；/index 被守卫重定向回当前页时刷新给出可见反馈 */
pushDefaultIndex() {
  const done = this.$router.push({ path: '/index' })
  if (done && typeof done.catch === 'function') {
    done.catch((error) => {
      if (error && error._isRouter && error.name !== 'NavigationDuplicated') return
      window.location.reload()
    })
  }
},

