// 门户首页：未登录访问时不带 redirect，直接落对外首页（禅道 5983）。
// 从管理端点「返回首页」会整页跳到 /index；门户有登录记录时上面的 hasToken
// 分支会放行 /index（对内首页），没有记录时才走这里。其它受保护路由仍保留
// redirect，避免用户从深链登录后丢失原目标页。
const PORTAL_HOME_PATHS = ['/index', '/']

// 处理未登录状态下的路由跳转
const handleUnauthenticatedRoutes = (to, next) => {
  if (whiteList.includes(to.path) || whiteList.includes(to.name)) {
    next()
  } else if (PORTAL_HOME_PATHS.includes(to.path)) {
    next(withPortalCategory('/UnifiedLogin'))
  } else {
    next(withPortalCategory(`/UnifiedLogin?redirect=${encodeURIComponent(to.fullPath)}`))
  }
}

